/**
 * Drive file → CoinDuel CDN paths + one manifest item.
 * Permanent game URL never changes:
 * https://cdn.jsdelivr.net/gh/Meyyds34555343/LiteProjects@behavior-scratch/cdn/manifest.json
 */
const cfg = $('Repo Config').first().json;
const drive = $('Google Drive Trigger').first().json;
const bin = $input.first().binary?.data;
if (!bin) throw new Error('No binary from Drive download');

const rawName = String(drive.name || bin.fileName || 'asset.png');
const base = rawName.replace(/\.[^.]+$/, '').replace(/[^a-zA-Z0-9_-]/g, '_').toLowerCase() || 'asset';
const ext = (rawName.match(/\.([a-z0-9]+)$/i)?.[1] || 'png').toLowerCase();
const mime = String(drive.mimeType || bin.mimeType || 'application/octet-stream');

const isImage = /^image\//i.test(mime) || /^(png|jpe?g|webp|gif)$/i.test(ext);
if (!isImage) {
  return [{ json: { skip: true, reason: `not an image: ${mime} ${rawName}` } }];
}

const textureRel = `textures/${base}.${ext === 'jpeg' ? 'jpg' : ext}`;
const texturePath = `${cfg.cdnPrefix}/${textureRel}`;
const hash = `gdrive-${base}-${Date.now().toString(36)}`;
const permanentUrl = `${String(cfg.jsdelivrBase).replace(/\/$/, '')}/${textureRel}`;

// Game AssetManifest item (relative filename; base resolved from manifest URL dir)
const manifestItem = {
  filename: textureRel,
  hash,
  kind: 'texture',
  // optional absolute URL — AssetSync accepts either
  url: permanentUrl,
};

return [{
  json: {
    skip: false,
    owner: cfg.owner,
    repo: cfg.repo,
    branch: cfg.branch,
    githubToken: cfg.githubToken || $vars.GITHUB_PAT || $vars.githubToken || '',
    texturePath,
    textureRel,
    hash,
    permanentUrl,
    manifestPath: `${cfg.cdnPrefix}/manifest.json`,
    manifestItem,
    commitMessage: `cdn: sync ${textureRel} from Google Drive`,
    driveFileId: drive.id,
    driveName: rawName,
  },
  binary: {
    data: bin,
  },
}];

/**
 * Upsert (= GET sha → PUT same path) for:
 *   cdn/textures/{name}.png
 *   cdn/manifest.json   ← ALWAYS the same path (permanent jsDelivr link)
 */
const item = $input.first().json;
const bin = $input.first().binary?.data;
if (!item.githubToken) throw new Error('Set Repo Config.githubToken (or $vars.GITHUB_PAT)');
if (!bin?.data) throw new Error('Missing file binary');

const token = item.githubToken;
const api = `https://api.github.com/repos/${item.owner}/${item.repo}/contents`;
const headers = {
  Authorization: `Bearer ${token}`,
  Accept: 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'n8n-coinduel-cdn',
};

async function getSha(path) {
  const url = `${api}/${path}?ref=${encodeURIComponent(item.branch)}`;
  const res = await this.helpers.httpRequest({ method: 'GET', url, headers, ignoreHttpStatusErrors: true });
  if (res && res.sha) return res.sha;
  return null;
}

async function putFile(path, contentBase64, message, sha) {
  const body = {
    message,
    content: contentBase64,
    branch: item.branch,
  };
  if (sha) body.sha = sha; // required to OVERWRITE same path
  const url = `${api}/${path}`;
  return this.helpers.httpRequest({ method: 'PUT', url, headers, body, json: true });
}

async function getJsonFile(path) {
  const url = `${api}/${path}?ref=${encodeURIComponent(item.branch)}`;
  const res = await this.helpers.httpRequest({ method: 'GET', url, headers, ignoreHttpStatusErrors: true });
  if (!res || !res.content) return { sha: null, json: null };
  const text = Buffer.from(res.content, 'base64').toString('utf8');
  try {
    return { sha: res.sha, json: JSON.parse(text) };
  } catch {
    return { sha: res.sha, json: null };
  }
}

// 1) Upsert texture at FIXED path cdn/textures/...
const texSha = await getSha.call(this, item.texturePath);
await putFile.call(this, item.texturePath, bin.data, item.commitMessage, texSha);

// 2) Load / create manifest, merge item by filename, upsert SAME manifest.json
const { sha: manSha, json: existing } = await getJsonFile.call(this, item.manifestPath);
const manifest = existing && typeof existing === 'object' ? existing : {
  version: 1,
  baseUrl: '',
  memeConfig: 'memes/index.json',
  items: [],
};
if (!Array.isArray(manifest.items)) manifest.items = [];

const idx = manifest.items.findIndex((x) => x && x.filename === item.manifestItem.filename);
if (idx >= 0) manifest.items[idx] = { ...manifest.items[idx], ...item.manifestItem };
else manifest.items.push(item.manifestItem);

manifest.version = Number(manifest.version || 0) + 1;

const manB64 = Buffer.from(JSON.stringify(manifest, null, 2), 'utf8').toString('base64');
await putFile.call(
  this,
  item.manifestPath,
  manB64,
  `cdn: bump manifest for ${item.textureRel}`,
  manSha,
);

return [{
  json: {
    ok: true,
    texturePath: item.texturePath,
    permanentTextureUrl: item.permanentUrl,
    permanentManifestUrl: `${item.permanentUrl.replace(/\/textures\/.*$/, '')}/manifest.json`.replace(/cdn\/cdn/, 'cdn') ||
      `https://cdn.jsdelivr.net/gh/${item.owner}/${item.repo}@${item.branch}/cdn/manifest.json`,
    manifestVersion: manifest.version,
    itemCount: manifest.items.length,
    note: 'jsDelivr may lag 1–5 min; game URL never changes',
  },
}];
